contract BadTWAP {
    IUniswapV3Pool immutable pool;
    uint256 constant WINDOW = 30 minutes;

    function getTwap() external view returns (uint256) {
        (int56 tickCumulative, ) = pool.observe(uint32[](WINDOW));
