correct_example.code:
contract GoodTWAP {
    IUniswapV3Pool immutable pool;
    uint256 constant MAX_WINDOW = 30 minutes;

    function getTwap(uint256 period) external view returns (uint256) {
        require(period > 0 && period <= MAX_WINDOW, "invalid window");
        uint32[] memory secondsAgos = new uint32[](2);
        secondsAgos[0] = uint32(period);
        secondsAgos[1] = 0;
        (int56[] memory tickCumulatives, ) = pool.observe(secondsAgos);
        // tickCumulatives[0] = cumulative at start, [1] = cumulative at end
        int256 delta = int256(tickCumulatives[1]) - int256(tickCumulatives[0]);
        // @audit divide by actual elapsed time (period)
        int256 avgTick = delta / int256(period);
        return uint256(avgTick);
    }
}
